dataSet.query:
ВЫБРАТЬ РАЗРЕШЕННЫЕ полис.Страхователь КАК Страхователь, МИНИМУМ(полис.ДатаНачала) КАК ДатаНачала, уб_ЗаменаПолисовСрезПоследних.АннулированныйПолис КАК АннулированныйПолис ПОМЕСТИТЬ ДатыПервыхПолисов ИЗ Документ.уб_СтраховойПолис КАК полис ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.уб_ЗаменаПолисов.СрезПоследних КАК уб_ЗаменаПолисовСрезПоследних ПО (уб_ЗаменаПолисовСрезПоследних.НовыйПолис = полис.Ссылка) ГДЕ НЕ полис.СостояниеПолиса В (ЗНАЧЕНИЕ(Перечисление.уб_СостоянияПолиса.АннулированПолностью), ЗНАЧЕНИЕ(Перечисление.уб_СостоянияПолиса.АннулированЗаменаБланка), ЗНАЧЕНИЕ(Перечисление.уб_СостоянияПолиса.АннулированВыписанНовый)) И полис.СтраховаяПремия > 0 И уб_ЗаменаПолисовСрезПоследних.АннулированныйПолис ЕСТЬ NULL
СГРУППИРОВАТЬ ПО полис.Страхователь, уб_ЗаменаПолисовСрезПоследних.АннулированныйПолис ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ОП.Ссылка КАК Оплата, ОП.СтраховойПолис.Заявка КАК Заявка, ОП.СтраховойПолис.Заявка.Менеджер КАК Менеджер, ОП.СтраховойПолис.Заявка.Страхователь КАК Страхователь, ОП.СтраховойПолис.Заявка КАК СтраховойПолисЗаявка, ОП.СтраховойПолис.Заявка.Источник КАК Источник, ОП.СтраховойПолис.Заявка.ДатаСоздания КАК ДатаСоздания, ОП.СтраховойПолис.Номер КАК НомерПолиса, СУММА(ОП.НачисленнаяСуммаВзноса) КАК НачисленнаяСуммаВзноса, СУММА(ВЫБОР КОГДА ОП.ОплаченоФакт > 0 И ОП.КВСуммаДляАгента >= ОП.АВилиСкидкаСумма ТОГДА ОП.КВСуммаДляАгента - ОП.АВилиСкидкаСумма ИНАЧЕ 0 КОНЕЦ * (100 - ОП.ПроцентСКВ) / 100) КАК СКВ, СУММА(ОП.КВСуммаДляАгента) КАК КВСумма, ВЫРАЗИТЬ(ВЫБОР КОГДА СУММА(ОП.НачисленнаяСуммаВзноса) = 0 ТОГДА 0 ИНАЧЕ СУММА(ОП.КВСуммаДляАгента) * 100 / СУММА(ОП.НачисленнаяСуммаВзноса) КОНЕЦ КАК ЧИСЛО(15, 2)) КАК КВПроцент, ВЫБОР КОГДА ОП.НомерВзноса = 1 И РАЗНОСТЬДАТ(ДатыПервыхПолисов.ДатаНачала, ОП.СтраховойПолис.Заявка.ДатаСоздания, МЕСЯЦ) < 3 ТОГДА 1 ИНАЧЕ 0 КОНЕЦ КАК НовыйКлиент, ОП.ВидСП КАК ВидСП ПОМЕСТИТЬ Оплаты ИЗ Документ.уб_ОплатаПолисов КАК ОП ЛЕВОЕ СОЕДИНЕНИЕ ДатыПервыхПолисов КАК ДатыПервыхПолисов ПО ОП.СтраховойПолис.Страхователь = ДатыПервыхПолисов.Страхователь ГДЕ ОП.ИсключитьИзРасчетаЗП = ЛОЖЬ И НЕ ОП.СтраховойПолис.Ссылка = ЗНАЧЕНИЕ(Документ.уб_СтраховойПолис.ПустаяСсылка) И ОП.СтраховойПолис.ПометкаУдаления = ЛОЖЬ И ОП.ПометкаУдаления = ЛОЖЬ И ОП.НеВключатьВОтчетыПоставщикам = ЛОЖЬ И ОП.СхемаРасчетаСМенеджером = ЗНАЧЕНИЕ(ПланВидовРасчета.уб_РасчетЗарплатыМенеджерамОП.ПланПоСКВ) И ВЫБОР КОГДА &ДатаОкончания > ДАТАВРЕМЯ(2026, 2, 1) И ОП.ЗарплатныйПериод >= &ДатаНачала И ОП.ЗарплатныйПериод <= &ДатаОкончания ТОГДА ИСТИНА КОГДА ОП.СтраховойПолис.Заявка.Дата > ДАТАВРЕМЯ(2026, 2, 1) и &ДатаНачала = ДАТАВРЕМЯ(2026, 2, 1) И ОП.ЗарплатныйПериод >= ДАТАВРЕМЯ(2026, 1, 1) И ОП.ЗарплатныйПериод <= ДАТАВРЕМЯ(2026, 1, 31) ТОГДА ИСТИНА КОГДА &ДатаОкончания < ДАТАВРЕМЯ(2026, 2, 1) И ОП.СтраховойПолис.Заявка.Дата >= &ДатаНачала И ОП.СтраховойПолис.Заявка.Дата <= &ДатаОкончания ТОГДА ИСТИНА ИНАЧЕ ЛОЖЬ КОНЕЦ И ОП.СтраховойПолис.Заявка.Источник = "Рекомендация" И ОП.СтраховойПолис.Заявка.Тип = ЗНАЧЕНИЕ(Перечисление.уб_ТипВыезда.Страховка) И ОП.СК.Наименование <> "-- КупиПолис --" И ОП.НомерВзноса = 1 И ОП.НачисленнаяСуммаВзноса >= 1000
СГРУППИРОВАТЬ ПО ОП.Ссылка, ОП.СтраховойПолис.Заявка.Менеджер, ОП.СтраховойПолис.Заявка.Страхователь, ОП.СтраховойПолис.Заявка, ОП.СтраховойПолис.Номер, ОП.СтраховойПолис.Заявка.Источник, ОП.СтраховойПолис.Заявка.ДатаСоздания, ВЫБОР КОГДА ОП.НомерВзноса = 1 И РАЗНОСТЬДАТ(ДатыПервыхПолисов.ДатаНачала, ОП.СтраховойПолис.Заявка.ДатаСоздания, МЕСЯЦ) < 3 ТОГДА 1 ИНАЧЕ 0 КОНЕЦ, ОП.ВидСП, ОП.СтраховойПолис.Заявка ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ОП.Заявка КАК Заявка, ОП.Менеджер КАК Менеджер, СУММА(ВЫБОР КОГДА ОП.ВидСП = ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.Осаго) ИЛИ ОП.ВидСП = ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.ЕОсаго) ТОГДА 1 ИНАЧЕ 0 КОНЕЦ) КАК ОСАГО, МАКСИМУМ(ВЫБОР КОГДА ОП.ВидСП = ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.Осаго) ИЛИ ОП.ВидСП = ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.ЕОсаго) ТОГДА ОП.НомерПолиса ИНАЧЕ "" КОНЕЦ) КАК ОСАГОНомер, СУММА(ВЫБОР КОГДА ОП.ВидСП = ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.Каско) ИЛИ ОП.ВидСП = ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.ЕКаско) ТОГДА 1 ИНАЧЕ 0 КОНЕЦ) КАК Каско, МАКСИМУМ(ВЫБОР КОГДА ОП.ВидСП = ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.Каско) ИЛИ ОП.ВидСП = ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.ЕКаско) ТОГДА ОП.НомерПолиса ИНАЧЕ "" КОНЕЦ) КАК КаскоНомер, СУММА(ОП.КВСумма) КАК КВСумма, уб_ДвижениеФизлицПоПодразделениямСрезПоследних.Подразделение КАК Подразделение, СУММА(ОП.НачисленнаяСуммаВзноса) КАК НачисленнаяСуммаВзноса ПОМЕСТИТЬ Данные ИЗ Оплаты КАК ОП ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.уб_ДвижениеФизлицПоПодразделениям.СрезПоследних КАК уб_ДвижениеФизлицПоПодразделениямСрезПоследних ПО ОП.Менеджер = уб_ДвижениеФизлицПоПодразделениямСрезПоследних.Агент ГДЕ ОП.ВидСП В (ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.Каско), ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.ЕКаско), ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.Осаго), ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.ЕОсаго)) И ВЫБОР КОГДА ОП.Заявка.Дата >= ДАТАВРЕМЯ(2024, 5, 1) ТОГДА ВЫБОР КОГДА ОП.НовыйКлиент = 1 ТОГДА ИСТИНА ИНАЧЕ ЛОЖЬ КОНЕЦ ИНАЧЕ ИСТИНА КОНЕЦ
СГРУППИРОВАТЬ ПО ОП.Заявка, ОП.Менеджер, уб_ДвижениеФизлицПоПодразделениямСрезПоследних.Подразделение ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ Данные.Заявка КАК Заявка, 1 КАК Количество, Данные.Менеджер КАК Менеджер, Данные.ОСАГО КАК ОСАГО, Данные.ОСАГОНомер КАК ОСАГОНомер, Данные.Каско КАК Каско, Данные.КаскоНомер КАК КаскоНомер, Данные.Подразделение КАК Подразделение, уб_ЗП_ПоказателиРасчетаЗП.РекомендацияКаско КАК РекомендацияКаско, уб_ЗП_ПоказателиРасчетаЗП.РекомендацияОсаго КАК РекомендацияОсаго, уб_ЗП_ПоказателиРасчетаЗП.РекомендацияКаскоПлюсОсаго КАК РекомендацияКаскоПлюсОсаго, ВЫБОР КОГДА Данные.ОСАГО > 0 И Данные.Каско > 0 ТОГДА уб_ЗП_ПоказателиРасчетаЗП.РекомендацияКаскоПлюсОсаго КОГДА Данные.Каско > 0 ТОГДА уб_ЗП_ПоказателиРасчетаЗП.РекомендацияКаско КОГДА Данные.ОСАГО > 0 ТОГДА уб_ЗП_ПоказателиРасчетаЗП.РекомендацияОсаго ИНАЧЕ 0 КОНЕЦ КАК Вознаграждение, Данные.КВСумма КАК КВСумма, Данные.НачисленнаяСуммаВзноса КАК НачисленнаяСуммаВзноса ПОМЕСТИТЬ Рекомендации ИЗ Данные КАК Данные ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.уб_ЗП_ПоказателиРасчетаЗП.СрезПоследних(&ДатаОкончания, ) КАК уб_ЗП_ПоказателиРасчетаЗП ПО (ИСТИНА) ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ Ставки.Период КАК Период, Ставки.СуммаЗаПовышенныйКВ_НБ КАК СуммаЗаПовышенныйКВ_НБ, Ставки.СуммаЗаПовышенныйКВ_Пролонгация КАК СуммаЗаПовышенныйКВ_Пролонгация, Ставки.СтавкаПроцентаПовышенныйКВ КАК СтавкаПроцентаПовышенныйКВ, Ставки.РекомендацияКаско КАК РекомендацияКаско, Ставки.РекомендацияОсаго КАК РекомендацияОсаго, Ставки.РекомендацияКаскоПлюсОсаго КАК РекомендацияКаскоПлюсОсаго ПОМЕСТИТЬ Ставки ИЗ РегистрСведений.уб_ЗП_ПоказателиРасчетаЗП.СрезПоследних(&ДатаОкончания, ) КАК Ставки ;
